          { id: "qna-d-ucb-02", level: 1, q: "What does 'effective memory length' mean for discounted UCB, and how does the discount factor control it?", difficulty: "medium" },
          { id: "qna-d-ucb-03", level: 1, q: "Why would you describe discounted UCB's behavior as 'smoother' than sliding window UCB's, and what does that smoothness buy you?", difficulty: "medium" },
          { id: "qna-d-ucb-04", level: 2, q: "Given both approaches solve the same forgetting problem, what would push you to pick discounted UCB over sliding window UCB, or vice versa?", difficulty: "hard" }
