          { id: "qna-rexp3-02", level: 1, q: "How does restarting EXP3 in epochs help control regret when there are multiple change points in an adversarial setting?", difficulty: "medium" },
          { id: "qna-rexp3-03", level: 2, q: "If you don't know the number of change points ahead of time, what approach still lets you bound regret, and what do you give up by not knowing it?", difficulty: "hard" }
