          { id: "qna-seasonality-02", level: 1, q: "Why would applying a forgetting mechanism like a sliding window or discount factor to seasonal data actually hurt performance instead of helping?", difficulty: "medium" },
          { id: "qna-seasonality-03", level: 1, q: "What's the right way to handle predictable time-of-day or day-of-week effects instead of treating them as drift to be forgotten?", difficulty: "medium" },
          { id: "qna-seasonality-04", level: 2, q: "In a production setting that's mostly stochastic with occasional abrupt shifts, why would sliding-window or discounted UCB typically beat EXP3 despite EXP3 having the stronger worst-case guarantee?", difficulty: "hard" }
