          { id: "qna-evalue-benchmark-02", level: 1, q: "Why would an E-value that's smaller than the association of a covariate you're already controlling for be treated as a real threat rather than a technicality?", difficulty: "medium" },
          { id: "qna-evalue-reporting-honesty-01", level: 2, q: "If benchmarking your E-value against observed covariates undermines your own result, what's the right way to handle that in how you report it?", difficulty: "medium" }
