          { id: "qna-sensitivity-reporting-standard-01", level: 1, q: "Why has reporting a sensitivity bound alongside an observational causal estimate become close to a standard expectation rather than an optional extra?", difficulty: "medium" },
          { id: "qna-sensitivity-specification-checks-01", level: 2, q: "Beyond a single sensitivity bound, what does a thorough robustness check of a causal estimate typically involve varying or comparing?", difficulty: "medium" }
