          { id: "qna-curve-diag-02", level: 1, q: "How do you tell the difference between 'augmentation is working as a regularizer' and 'augmentation is too aggressive and actively hurting the model,' just by looking at the curves?", difficulty: "medium" },
          { id: "qna-curve-diag-03", level: 2, q: "A colleague sees training accuracy drop after you add augmentation and wants to dial it back immediately. How do you respond, and under what curve pattern would they actually be right?", difficulty: "hard" }
