          { id: "qna-highpass-lowpass-01", level: 1, q: "In what sense does the Laplacian act as a high-pass filter and typical GCN aggregation act as a low-pass filter on node features? What's actually being filtered?", difficulty: "medium" },
          { id: "qna-oversmoothing-01", level: 1, q: "What is over-smoothing in a GNN, and mechanically why does it get worse the more layers you stack?", difficulty: "medium" },
          { id: "qna-oversmoothing-diagnosis-01", level: 2, q: "If a GNN's accuracy degrades as you add depth, how would you distinguish over-smoothing from an ordinary optimization or overfitting problem, and how would the fix differ for each?", difficulty: "hard" }
