          { id: "qna-concept-drift-def-02", level: 0, q: "In a deployed ML system, is concept drift fundamentally a data problem, a labeling problem, or something else? Where does it actually originate?", difficulty: "easy" },
          { id: "qna-concept-drift-vs-data-drift-01", level: 1, q: "Concept drift versus feature/data drift — can you have one without the other, and does telling them apart actually change what you'd do in response?", difficulty: "medium" },
          { id: "qna-concept-drift-signal-01", level: 1, q: "Why can a feature's distribution look completely normal on your dashboards while the model's predictions are already meaningfully wrong?", difficulty: "medium" }
