          { id: "qna-surge-smoothing-mechanism-01", level: 1, q: "How does smoothing actually prevent oscillation — what specifically is it rate-limiting?", difficulty: "medium" },
          { id: "qna-surge-hysteresis-vs-smoothing-01", level: 1, q: "What's the difference between hysteresis/deadbands and smoothing? What failure mode does each one specifically target that the other doesn't?", difficulty: "medium" },
          { id: "qna-surge-cap-only-gap-01", level: 2, q: "If you implemented a hard cap on the surge multiplier but skipped smoothing and hysteresis entirely, what instability could still happen underneath that cap?", difficulty: "hard" }
