          { id: "qna-surge-explainability-mechanism-01", level: 1, q: "Why does simply explaining a price increase ('prices are higher due to demand') reduce the perception of exploitation, even when the multiplier itself doesn't change at all?", difficulty: "medium" },
          { id: "qna-surge-disablement-tradeoff-01", level: 2, q: "What does a marketplace actually give up, mechanically, by disabling or capping surge during an emergency? Why isn't this a free fix?", difficulty: "hard" }
