          { id: "qna-control-group-02", level: 1, q: "Why does 'incremental equals treated minus control' give you a cleaner uplift number than just looking at the treated group's sales on their own?", difficulty: "medium" },
          { id: "qna-control-window-scope-01", level: 1, q: "Why does the control-group fix need to be paired with both a longer time window and a wider, category-level scope — what specifically does each of those two changes catch that the other one wouldn't?", difficulty: "medium" },
          { id: "qna-control-group-03", level: 2, q: "What are the practical costs or risks of running a no-promo holdout group, and why might a team be tempted to skip it even knowing about baseline leakage?", difficulty: "medium" }
