          { id: "qna-umap-tuning-02", level: 1, q: "If a UMAP plot instead shows many tiny, isolated clusters rather than a few coherent groups, what does that suggest about your parameter settings?", difficulty: "medium" },
          { id: "qna-embedding-robustness-01", level: 2, q: "How would you decide whether a cluster structure you see in a t-SNE or UMAP embedding reflects genuine structure in the data, versus being an artifact of the specific settings you chose?", difficulty: "hard" }
